begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000227901','engage-privacy@test.invalid');
insert into public.profiles(id,display_name) values('00000000-0000-4000-8000-000000227901','Engage privacy');
insert into public.tenants(id,name,slug) values('10000000-0000-4000-8000-000000227901','Engage privacy','engage-privacy-s227');
insert into public.tenant_settings(tenant_id) values('10000000-0000-4000-8000-000000227901');
insert into public.tenant_feature_flags(tenant_id,flag_key,enabled,rollout_reason) values('10000000-0000-4000-8000-000000227901','engage',true,'Isolated Engage privacy regression');
insert into public.engage_campaigns(id,public_id,tenant_id,kind,status,title,question,result_visibility)
select ('21000000-0000-4000-8000-00000022790'||n)::uuid,('22000000-0000-4000-8000-00000022790'||n)::uuid,'10000000-0000-4000-8000-000000227901','poll','live','Eigen poll '||n,'Eigen vraag '||n,policy
from (values(1,'after_close'),(2,'after_vote'),(3,'live')) x(n,policy);
insert into public.engage_options(id,tenant_id,campaign_id,label,sort_order)
select (prefix||'0000-4000-8000-00000022790'||n)::uuid,'10000000-0000-4000-8000-000000227901',('21000000-0000-4000-8000-00000022790'||n)::uuid,label,sort_order
from generate_series(1,3)n cross join(values('31000000-','Keuze A',0),('32000000-','Keuze B',1))x(prefix,label,sort_order);
create temp table responses(name text primary key,payload jsonb);
grant all on responses to service_role;
set local role service_role;
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227901',repeat('a',64))->>'resultsVisible')::boolean,false,'after_close is hidden before voting');
insert into responses values('close_accept',public.submit_engage_vote_v1('22000000-0000-4000-8000-000000227901','31000000-0000-4000-8000-000000227901',repeat('a',64),repeat('b',64)));
insert into responses values('close_duplicate',public.submit_engage_vote_v1('22000000-0000-4000-8000-000000227901','32000000-0000-4000-8000-000000227901',repeat('a',64),repeat('b',64)));
select is((select payload->>'reason' from responses where name='close_accept'),'accepted','first vote is accepted');
select is((select payload->>'reason' from responses where name='close_duplicate'),'already_voted','a changed-option replay is not a second vote');
select is((select payload#>>'{campaign,resultsVisible}' from responses where name='close_accept'),'false','after_close receipt cannot reveal results');
select is((select payload#>>'{campaign,totalVotes}' from responses where name='close_accept'),'0','after_close receipt cannot reveal tally');
select ok((select not jsonb_path_exists(payload,'$.campaign.options[*].voteCount') from responses where name='close_accept'),'after_close receipt omits every option count');
select is((select payload#>>'{campaign,resultsVisible}' from responses where name='close_duplicate'),'false','after_close duplicate receipt remains private');
select ok((select not jsonb_path_exists(payload,'$.campaign.options[*].voteCount') from responses where name='close_duplicate'),'duplicate receipt also omits option counts');
insert into responses values('close_identity',public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227901',repeat('a',64)));
select is((select payload->>'resultsVisible' from responses where name='close_identity'),'false','voted identity cannot bypass after_close');
select is((select payload->>'totalVotes' from responses where name='close_identity'),'0','identity read hides total votes');
select ok((select not jsonb_path_exists(payload,'$.options[*].voteCount') from responses where name='close_identity'),'identity read omits every option count');
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227902',repeat('a',64))->>'resultsVisible')::boolean,false,'after_vote is hidden before voting');
insert into responses values('vote_accept',public.submit_engage_vote_v1('22000000-0000-4000-8000-000000227902','31000000-0000-4000-8000-000000227902',repeat('a',64),repeat('b',64)));
select is((select payload#>>'{campaign,resultsVisible}' from responses where name='vote_accept'),'true','after_vote receipt reveals the actual accepted tally');
select is((select payload#>>'{campaign,totalVotes}' from responses where name='vote_accept'),'1','after_vote tally is one');
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227902',repeat('a',64))->>'resultsVisible')::boolean,true,'after_vote voter can reread results');
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227902',repeat('c',64))->>'resultsVisible')::boolean,false,'another identity cannot read after_vote results');
select is((public.get_engage_campaign_public_v1('22000000-0000-4000-8000-000000227902')->>'resultsVisible')::boolean,false,'anonymous public read remains hidden for after_vote');
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227903',repeat('c',64))->>'resultsVisible')::boolean,true,'live results are public before voting');
insert into responses values('live_accept',public.submit_engage_vote_v1('22000000-0000-4000-8000-000000227903','31000000-0000-4000-8000-000000227903',repeat('a',64),repeat('b',64)));
select is((select payload#>>'{campaign,totalVotes}' from responses where name='live_accept'),'1','live receipt retains its actual tally');
reset role;
select is((select count(*) from public.engage_votes where tenant_id='10000000-0000-4000-8000-000000227901'),3::bigint,'only one real vote was stored per campaign');
select is((select option_id from public.engage_votes where campaign_id='21000000-0000-4000-8000-000000227901'),'31000000-0000-4000-8000-000000227901'::uuid,'duplicate did not change the original option');
update public.engage_campaigns set status='closed' where tenant_id='10000000-0000-4000-8000-000000227901';
set local role service_role;
select ok(bool_and((public.get_engage_campaign_public_v1(('22000000-0000-4000-8000-00000022790'||n)::uuid)->>'resultsVisible')::boolean),'all policies expose closed results') from generate_series(1,3)n;
select is((public.get_engage_campaign_public_v1('22000000-0000-4000-8000-000000227901')->>'totalVotes'),'1','closing reveals the preserved true tally');
select is((public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227901',repeat('c',64))->>'resultsVisible')::boolean,true,'closed results are available to a new visitor');
select is((public.submit_engage_vote_v1('22000000-0000-4000-8000-000000227901','31000000-0000-4000-8000-000000227901',repeat('c',64),repeat('d',64))->>'reason'),'closed','late vote retains the existing closed RPC response');
reset role;
select is((select count(*) from public.engage_votes where tenant_id='10000000-0000-4000-8000-000000227901'),3::bigint,'late vote made no new vote');
update public.engage_campaigns set status='archived' where tenant_id='10000000-0000-4000-8000-000000227901';
set local role service_role;
select is(public.get_engage_campaign_for_identity_v1('22000000-0000-4000-8000-000000227901',repeat('a',64)),null::jsonb,'archive remains unavailable to a prior voter');
reset role;
select is(has_function_privilege('anon','public.submit_engage_vote_v1(uuid,uuid,text,text)','execute'),false,'anonymous role cannot invoke privileged voting directly');
select is(has_function_privilege('authenticated','public.submit_engage_vote_v1(uuid,uuid,text,text)','execute'),false,'authenticated role cannot invoke privileged voting directly');
select is(has_function_privilege('authenticated','public.get_engage_campaign_for_identity_v1(uuid,text)','execute'),false,'authenticated role cannot access identity read directly');
select is(has_function_privilege('service_role','public.submit_engage_vote_v1(uuid,uuid,text,text)','execute'),true,'service role retains its bounded voting command');
select is(has_function_privilege('authenticated','private.engage_public_payload_v1(uuid,boolean)','execute'),false,'shared payload boundary remains private');
select ok((select prosecdef and provolatile='s' and proconfig @> array['search_path=""'] from pg_proc where oid='private.engage_public_payload_v1(uuid,boolean)'::regprocedure),'shared payload keeps STABLE SECURITY DEFINER and empty search_path');
select * from finish();
rollback;
